```javascript
function findObjectByName(obj, targetName) {
    const stack = [{ obj: obj, path: [] }];

    while (stack.length > 0) {
        const { obj, path } = stack.pop();

        if (obj.name === targetName) {
            return { foundObj: obj, path };
        }

        Object.keys(obj).forEach(key => {
            if (typeof obj[key] === 'object' && obj[key] !== null) {
                stack.push({ obj: obj[key], path: [...path, key] });
            }
        });
    }

    return { foundObj: null, path: [] };
}

// Example usage:
const nestedObject = {
    level1: {
        level2a: {
            name: 'target',
            value: 42
        },
        level2b: {
            name: 'notTarget',
            subLevel: {
                name: 'anotherNotTarget'
            }
        }
    },
    level1b: {
        name: 'yetAnotherNotTarget'
    }
};

const result = findObjectByName(nestedObject, 'target');
console.log(result.foundObj); // Output: { name: 'target', value: 42 }
console.log(result.path);     // Output: ['level1', 'level2a']
```

This function uses a stack to simulate the behavior of a non-recursive depth-first search. It iterates through each property of the current object, pushing new objects onto the stack with their respective paths until it finds the desired object or exhausts all possibilities. If the object is found, it returns the object along with the path; otherwise, it returns `null` for the object and an empty array for the path.

