Certainly! Below is an example of a Python script using Object-Oriented Programming (OOP) to implement a Contextual Multi-Armed Bandit problem with three models.

```python
import numpy as np

class Model:
    def __init__(self):
        self.weights = None

    def fit(self, X, y):
        raise NotImplementedError("Subclasses must implement this method")

    def predict(self, X):
        raise NotImplementedError("Subclasses must implement this method")

class LinearModel(Model):
    def fit(self, X, y):
        # Simple linear regression using least squares
        self.weights = np.linalg.inv(X.T @ X) @ X.T @ y

    def predict(self, X):
        return X @ self.weights

class RandomModel(Model):
    def predict(self, X):
        return np.random.rand(len(X))

class EpsilonGreedyBandit:
    def __init__(self, epsilon=0.1, models=None):
        if models is None:
            models = [LinearModel(), RandomModel(), RandomModel()]
        self.epsilon = epsilon
        self.models = models
        self.best_model_index = None
        self.rewards = []

    def select_arm(self, context):
        if np.random.rand() < self.epsilon:
            arm = np.random.choice(len(self.models))
        else:
            predictions = [model.predict([context])[0] for model in self.models]
            arm = np.argmax(predictions)

        reward = self._get_reward(arm)
        self.rewards.append(reward)

        if self.best_model_index is None or reward > self._get_best_reward():
            self.best_model_index = arm

        return arm

    def _get_reward(self, arm):
        # Simulate getting a reward based on the selected arm
        return np.random.normal(loc=self.models[arm].predict([np.array([1])])[0], scale=1.0)

    def _get_best_reward(self):
        if self.best_model_index is not None:
            return self.models[self.best_model_index].predict([np.array([1])])[0]
        return -np.inf

# Example usage
if __name__ == "__main__":
    bandit = EpsilonGreedyBandit()
    contexts = np.random.rand(100, 1)  # Generate some random contexts

    for context in contexts:
        arm = bandit.select_arm(context)
        print(f"Selected Arm: {arm}, Reward: {bandit.rewards[-1]}")
```

### Explanation:

1. **Model Class**: This is an abstract base class that defines the interface for different types of models.
2. **LinearModel Class**: A simple linear regression model implemented using least squares.
3. **RandomModel Class**: A model that always returns a random prediction.
4. **EpsilonGreedyBandit Class**: Implements the epsilon-greedy strategy for selecting arms (models). It maintains a list of rewards and updates the best model index based on the observed rewards.
5. **Example Usage**: Demonstrates how to use the `EpsilonGreedyBandit` class by generating some random contexts and running the bandit algorithm.

This script provides a basic framework for implementing a contextual multi-armed bandit problem with multiple models. You can extend it further by adding more sophisticated models or modifying the reward function.

