        // Convert the fractional part to binary
        string fractionalPart = piString.Split('.')[1];
        string binaryFractionalPart = FractionToBinary(fractionalPart);

        // Combine both parts
        string fullBinaryRepresentation = binaryIntegerPart + "." + binaryFractionalPart;

        Console.WriteLine($"Binary Representation: {fullBinaryRepresentation}");

        // Perform XOR operation twice
        string xorResult = XorTwice(fullBinaryRepresentation);
        Console.WriteLine($"XOR Result: {xorResult}");
    }

    static double CalculatePi(int iterations)
    {
        double pi = 0;
        for (int i = 0; i < iterations; i++)
        {
            pi += Math.Pow(-1, i) / (2 * i + 1);
        }
        return 4 * pi;
    }

    static string FractionToBinary(string fraction)
    {
        StringBuilder sb = new StringBuilder();
        double num = double.Parse(fraction);
        while (num > 0 && sb.Length < 16) // Limiting to 16 bits after the decimal point
        {
            num *= 2;
            if (num >= 1)
            {
                sb.Append('1');
                num -= 1;
            }
            else
            {
                sb.Append('0');
            }
        }
        return sb.ToString();
    }

    static string XorTwice(string binaryStr)
    {
        char[] chars = binaryStr.ToCharArray();
        for (int i = 0; i < chars.Length; i++)
        {
            chars[i] ^= '1';
        }
        return new string(chars);
    }
}
```

