```c
#include <stdio.h>
#include <stdlib.h>

// Function prototype for adding reverb effect
void apply_reverb(float* buffer, int length);

// Implementation of the reverb function
void apply_reverb(float* buffer, int length) {
    // Simple reverb implementation using delay and feedback
    float delay = 0.5f; // Delay time in seconds
    float feedback = 0.7f; // Feedback gain

    for (int i = 0; i < length - 1; ++i) {
        float delayed_sample = buffer[i] * feedback;
        buffer[i + 1] += delayed_sample;
    }
}

// Exported function to be called from Java/Kotlin
JNIEXPORT void JNICALL Java_com_example_ReverbActivity_applyReverb(JNIEnv* env, jobject obj, jfloatArray buffer, jint length) {
    jfloat* data = (*env)->GetFloatArrayElements(env, buffer, NULL);
    apply_reverb(data, length);
    (*env)->ReleaseFloatArrayElements(env, buffer, data, 0);
}
```

Compile the C code into a shared library using the following command:

