Creating a smart contract for an ERC-1155 token with credentials (creds) involves defining the token's properties, functionalities, and rules. Below is a simplified example of how you might structure such a smart contract using Solidity.

Please note that this is a basic example and may need to be adapted or expanded based on your specific requirements. Always test thoroughly before deploying any smart contracts on a live network.

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC1155/ERC1155.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract CredsToken is ERC1155, Ownable {
    // Define the types of credentials
    enum CredentialType { Degree, Certification, Badge }

    // Mapping from credential type to its metadata URI
    mapping(CredentialType => string) private _credentialMetadataURIs;

    // Event emitted when a new credential is minted
    event CredentialMinted(address indexed account, uint256 id);

    constructor(string memory uriDegree, string memory uriCertification, string memory uriBadge) ERC1155("") {
        _setURI(uriDegree);
        _credentialMetadataURIs[CredentialType.Degree] = uriDegree;
        _credentialMetadataURIs[CredentialType.Certification] = uriCertification;
        _credentialMetadataURIs[CredentialType.Badge] = uriBadge;
    }

    function setCredentialMetadataURI(CredentialType credentialType, string memory uri) external onlyOwner {
        _credentialMetadataURIs[credentialType] = uri;
    }

    function getCredentialMetadataURI(CredentialType credentialType) public view returns (string memory) {
        return _credentialMetadataURIs[credentialType];
    }

    function mintCredentialedTokens(
        address[] calldata accounts,
        uint256[] calldata ids,
        uint256[] calldata amounts,
        bytes[] calldata data
    ) external onlyOwner {
        require(accounts.length == ids.length && ids.length == amounts.length, "Invalid input arrays");

        for (uint256 i = 0; i < accounts.length; ++i) {
            _mint(accounts[i], ids[i], amounts[i], data[i]);
            emit CredentialMinted(accounts[i], ids[i]);
        }
    }

    function burnCredentialedTokens(
        address account,
        uint256 id,
        uint256 amount,
        bytes calldata data
    ) external {
        require(balanceOf(account, id) >= amount, "Insufficient balance");
        _burn(account, id, amount);
    }

    function supportsInterface(bytes4 interfaceId) public view virtual override(ERC1155, IERC165) returns (bool) {
        return super.supportsInterface(interfaceId);
    }
}
```

This contract extends `ERC1155` and `Ownable`, allowing it to manage multiple token IDs and types while also providing ownership features. The `CredentialType` enum defines different types of credentials, and mappings store their respective metadata URIs.

The `mintCredentialedTokens` function allows the owner to mint tokens for specified accounts, while `burnCredentialedTokens` enables burning tokens by users themselves.

