```matlab
% Water Wave Simulation using MATLAB

% Parameters
L = 0.42; % Length of the tank (m)
W = 0.36; % Width of the tank (m)
U = 2.5; % Wind speed (m/s)

% Grid parameters
nx = 100; % Number of grid points along x-axis
ny = 100; % Number of grid points along y-axis
dx = L / (nx - 1); % Spatial step size along x-axis
dy = W / (ny - 1); % Spatial step size along y-axis

% Time parameters
dt = 0.01; % Time step size (s)
T = 10; % Total simulation time (s)
nt = round(T / dt); % Number of time steps

% Initialize variables
x = linspace(0, L, nx);
y = linspace(0, W, ny);
[X, Y] = meshgrid(x, y);

% Initial condition: flat surface
eta = zeros(nx, ny);

% Coefficients for wave equation
g = 9.81; % Acceleration due to gravity (m/s^2)
rho = 1000; % Density of water (kg/m^3)
kappa = U * sqrt(g / rho) / dx;

% Preallocate arrays for efficiency
eta_new = zeros(size(eta));
u = zeros(size(eta)); % Velocity field

% Main loop
for t = 1:nt
    % Update velocity field based on wind forcing
    u(:, :) = kappa * eta(:, :);

    % Update surface elevation using finite difference method
    eta_new(2:end-1, 2:end-1) = eta(2:end-1, 2:end-1) + ...
        dt * ((u(2:end-1, 2:end-1) - u(2:end-1, 1:end-2)) ./ dx + ...
              (u(2:end-1, 2:end-1) - u(1:end-2, 2:end-1)) ./ dy);

    % Apply boundary conditions
    eta_new(:, 1) = eta(:, 1); % No-slip at left wall
    eta_new(:, end) = eta(:, end); % No-slip at right wall
    eta_new(1, :) = eta(1, :); % No-slip at bottom wall
    eta_new(end, :) = eta(end, :); % No-slip at top wall

    % Update eta for next iteration
    eta = eta_new;

    % Plotting
    if mod(t, 10) == 0 || t == nt
        figure;
        surf(X, Y, eta');
        title(['Time = ', num2str(t*dt), ' s']);
        xlabel('X (m)');
        ylabel('Y (m)');
        zlabel('\eta (m)');
        colorbar;
        drawnow;
    end
end

disp('Simulation complete.');
```

